import heapq

def match(orders):
    book = {}
    sell_heap = []  # entries: (price, seq, id)
    buy_heap = []   # entries: (-price, seq, id)
    trades = []
    seq = 0

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid]['active'] = False
                del book[oid]
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty
        seq += 1
        cur_seq = seq

        heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and heap:
            if side == 'buy':
                top_price, top_seq, top_id = heap[0]
            else:
                neg_price, top_seq, top_id = heap[0]
                top_price = -neg_price

            if top_id not in book or not book[top_id]['active'] or book[top_id]['qty'] <= 0:
                heapq.heappop(heap)
                continue

            if typ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            resting = book[top_id]
            trade_qty = min(remaining, resting['qty'])

            if side == 'buy':
                trades.append([oid, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, oid, top_price, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] == 0:
                resting['active'] = False
                heapq.heappop(heap)
                del book[top_id]

            if remaining == 0:
                break

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, cur_seq, oid))
            else:
                heapq.heappush(sell_heap, (price, cur_seq, oid))
        # ioc/market remainder discarded

    return trades

